	'messages:prefs-help-email-allow-new-users' => 'en:Enabling this option will allow users who are not [[{{MediaWiki:grouppage-autoconfirmed}}|autoconfirmed]] to send you emails.',
	'messages:prefs-custom-cssjs-safemode' => 'en:Custom CSS/JavaScript are currently unavailable as safe mode has been enabled. Please [[#mw-input-wpforcesafemode|disable safe mode]] to use custom CSS/JavaScript.',
